21	    @Mapping(target = "displayName",
22	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
23	    @Mapping(target = "initials",
24	        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
25	    @Mapping(target = "membershipNumber",
26	        expression = "java(owner.getCustomerCode() == null || owner.getRegistrationDate() == null ? null : owner.getCustomerCode() + \"-M\" + String.format(\"%02d\", owner.getRegistrationDate().getYear() % 100))")
27	    @Mapping(target = "membershipTier",
28	        expression = "java(owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0 && owner.getEmail() != null && !owner.getEmail().isEmpty() ? \"SILVER\" : \"BRONZE\")")
29	    OwnerDto toOwnerDto(Owner owner);
30	
31	    Owner toOwner(OwnerDto ownerDto);
32	
33	    @Mapping(target = "id", ignore = true)
34	    @Mapping(target = "pets", ignore = true)
35	    Owner toOwner(OwnerFieldsDto ownerDto);
36	
37	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
38	
39	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
40	
41	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
42	        OwnerPageDto ownerPageDto = new OwnerPageDto();
43	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
44	        ownerPageDto.setPage(ownerPage.getNumber());
45	        ownerPageDto.setSize(ownerPage.getSize());
46	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
47	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
48	        return ownerPageDto;
49	    }
50	}
